d. Pseudo-classes.code:
/* États de liens */
a:link { color: blue; }
a:visited { color: purple; }
a:hover { color: red; }
a:active { color: orange; }
a:focus { outline: 2px solid blue; }

/* Pseudo-classes structurelles */
li:first-child { font-weight: bold; }
li:last-child { border-bottom: none; }
li:nth-child(odd) { background: #f0f0f0; }
li:nth-child(2n) { background: #e0e0e0; }
li:nth-child(3n+1) { color: red; }

/* États de formulaire */
input:required { border-left: 3px solid red; }
input:valid { border-color: green; }
input:invalid { border-color: red; }
input:disabled { opacity: 0.5; }

/* Autres pseudo-classes utiles */
:root { --primary-color: #007bff; }
:empty { display: none; }
:not(.special) { color: black; }

e. Pseudo-éléments.code:
/* Pseudo-éléments de contenu */
p::before {
  content: "→ ";
  color: blue;
  font-weight: bold;
}

p::after {
  content: " ←";
  color: red;
}

/* Première ligne et première lettre */
p::first-line {
  font-weight: bold;
  color: #333;
}

p::first-letter {
  font-size: 2em;
  float: left;
  margin-right: 5px;
}

/* Sélection de texte */
::selection {
  background: #007bff;
  color: white;
}

/* Placeholder dans les inputs */
input::placeholder {
  color: #999;
  font-style: italic;
}

