a. Conteneur Grid.code:
/* Activation du grid */
.grid-container {
  display: grid;
  /* ou display: inline-grid; */
}

/* Définition des colonnes */
.grid-columns {
  grid-template-columns: 200px 1fr 100px; /* 3 colonnes */
  grid-template-columns: repeat(3, 1fr); /* 3 colonnes égales */
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); /* Responsive */
}

/* Définition des lignes */
.grid-rows {
  grid-template-rows: 80px 1fr 60px; /* Header, contenu, footer */
  grid-template-rows: repeat(4, 100px); /* 4 lignes de 100px */
}

/* Espacement */
.grid-gap {
  gap: 1rem; /* Espacement uniforme */
  row-gap: 1rem;
  column-gap: 2rem;
}

/* Zones nommées */
.grid-areas {
  grid-template-areas:
    "header header header"
    "sidebar main main"
    "footer footer footer";
}

b. Placement des Éléments.code:
/* Placement par lignes */
.item-1 {
  grid-column-start: 1;
  grid-column-end: 3; /* S'étend sur 2 colonnes */
  grid-row-start: 1;
  grid-row-end: 2;
}

/* Raccourcis de placement */
.item-2 {
  grid-column: 1 / 3; /* Colonnes 1 à 3 */
  grid-row: 2 / 4; /* Lignes 2 à 4 */
}

/* Span pour étendre */
.item-3 {
  grid-column: span 2; /* S'étend sur 2 colonnes */
  grid-row: span 3; /* S'étend sur 3 lignes */
}

/* Placement par zones nommées */
.header { grid-area: header; }
.sidebar { grid-area: sidebar; }
.main { grid-area: main; }
.footer { grid-area: footer; }

/* Placement automatique */
.auto-item {
  grid-column: auto; /* Placement automatique */
  grid-row: auto;
}

/* Zone complète avec raccourci */
.full-item {
  grid-area: 1 / 1 / -1 / -1; /* Occupe toute la grille */
}

c. Alignement Grid.code:
/* Alignement des éléments dans leurs cellules */
.grid-container {
  justify-items: start; /* start, end, center, stretch */
  align-items: center; /* start, end, center, stretch */
}

/* Auto-alignement d'un élément */
.grid-item {
  justify-self: end;
  align-self: start;
}

/* Alignement de la grille dans le conteneur */
.grid-container {
  justify-content: center; /* start, end, center, stretch, space-around, space-between, space-evenly */
  align-content: center;
}

/* Raccourci place-items */
.grid-container {
  place-items: center; /* align-items justify-items */
  place-items: start end; /* align-items justify-items */
}

/* Raccourci place-content */
.grid-container {
  place-content: center; /* align-content justify-content */
}

/* Raccourci place-self */
.grid-item {
  place-self: end; /* align-self justify-self */
}

d. Layouts Grid Avancés.code:
/* Layout complet de page */
.page-layout {
  display: grid;
  min-height: 100vh;
  grid-template-areas:
    "header header header"
    "nav main sidebar"
    "footer footer footer";
  grid-template-columns: 200px 1fr 250px;
  grid-template-rows: auto 1fr auto;
  gap: 1rem;
}

/* Grille responsive avec auto-fit */
.responsive-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
  padding: 2rem;
}

/* Grille complexe avec différentes tailles */
.magazine-layout {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  grid-template-rows: repeat(4, 200px);
  gap: 1rem;
}

.featured-article {
  grid-column: 1 / 4;
  grid-row: 1 / 3;
}

.small-article {
  grid-column: span 2;
  grid-row: span 1;
}

/* Grille imbriquée */
.nested-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

.nested-item {
  display: grid;
  grid-template-rows: auto 1fr auto;
}

