b. Formatage du Texte.code:
/* Alignement du texte */
.text-align {
  text-align: left;
  text-align: center;
  text-align: right;
  text-align: justify;
}

/* Décoration du texte */
.text-decoration {
  text-decoration: none;
  text-decoration: underline;
  text-decoration: line-through;
  text-decoration: overline;
  text-decoration: underline wavy red; /* Style avancé */
}

/* Transformation du texte */
.text-transform {
  text-transform: uppercase;
  text-transform: lowercase;
  text-transform: capitalize;
  text-transform: none;
}

/* Espacement */
.text-spacing {
  line-height: 1.5; /* Hauteur de ligne */
  letter-spacing: 0.1em; /* Espacement des lettres */
  word-spacing: 0.2em; /* Espacement des mots */
  text-indent: 2em; /* Indentation première ligne */
}

/* Ombre du texte */
.text-shadow {
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
  text-shadow: 1px 1px 2px #000, 0 0 1em #ff0000; /* Multiples ombres */
