c. Gestion du Débordement.code:
/* Retour à la ligne */
.word-wrap {
  word-wrap: break-word; /* Casse les mots longs */
  word-break: break-all; /* Casse n'importe où */
  word-break: keep-all; /* Garde les mots entiers */
}

/* Espace blanc */
.white-space {
  white-space: normal; /* Défaut */
  white-space: nowrap; /* Pas de retour à la ligne */
  white-space: pre; /* Préserve espaces et retours */
  white-space: pre-wrap; /* Préserve + retour auto */
  white-space: pre-line; /* Retours préservés */
}

/* Ellipse pour texte tronqué */
.text-ellipsis {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* Ellipse multi-lignes */
.text-ellipsis-multiline {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3; /* Nombre de lignes */
  overflow: hidden;
}

/* Césure */
.hyphenation {
  hyphens: auto;
  -webkit-hyphens: auto;
  -ms-hyphens: auto;
}

