b. Arrière-plans.code:
/* Couleur de fond */
.background-color {
  background-color: #f8f9fa;
  background-color: rgba(0, 0, 0, 0.1);
}

/* Image de fond */
.background-image {
  background-image: url('image.jpg');
  background-image: linear-gradient(45deg, #ff6b6b, #4ecdc4);
  background-image: radial-gradient(circle, #ff6b6b, #4ecdc4);
}

/* Position de l'arrière-plan */
.background-position {
  background-position: center;
  background-position: top left;
  background-position: 50% 25%;
  background-position: center top;
}

/* Taille de l'arrière-plan */
.background-size {
  background-size: auto; /* Taille originale */
  background-size: cover; /* Couvre tout en gardant ratio */
  background-size: contain; /* Contient entièrement */
  background-size: 100% 50%; /* Largeur et hauteur */
}

/* Répétition */
.background-repeat {
  background-repeat: no-repeat;
  background-repeat: repeat;
  background-repeat: repeat-x;
  background-repeat: repeat-y;
}

/* Attachement */
.background-attachment {
  background-attachment: scroll; /* Défile avec le contenu */
