}

c. Dégradés.code:
/* Dégradés linéaires */
.linear-gradients {
  background: linear-gradient(to right, #ff6b6b, #4ecdc4);
  background: linear-gradient(45deg, #ff6b6b, #4ecdc4);
  background: linear-gradient(to bottom, #ff6b6b 0%, #4ecdc4 50%, #45b7d1 100%);
}

/* Dégradés radiaux */
.radial-gradients {
  background: radial-gradient(circle, #ff6b6b, #4ecdc4);
  background: radial-gradient(ellipse at center, #ff6b6b, #4ecdc4);
  background: radial-gradient(circle at top left, #ff6b6b, transparent);
}

/* Dégradés coniques */
.conic-gradients {
  background: conic-gradient(#ff6b6b, #4ecdc4, #45b7d1, #ff6b6b);
  background: conic-gradient(from 45deg, #ff6b6b, #4ecdc4);
}

/* Dégradés répétés */
.repeating-gradients {
  background: repeating-linear-gradient(
    45deg,
    #ff6b6b,
    #ff6b6b 10px,
    #4ecdc4 10px,
    #4ecdc4 20px
  );
}

/* Arrière-plans multiples */
.multiple-backgrounds {
  background:
    linear-gradient(rgba(255,255,255,0.3), rgba(255,255,255,0.3)),
    url('texture.png'),
    linear-gradient(45deg, #ff6b6b, #4ecdc4);
}

