a. Transformations 2D.code:
/* Translation (déplacement) */
.translate {
  transform: translate(50px, 100px); /* X et Y */
  transform: translateX(50px); /* Seulement X */
  transform: translateY(100px); /* Seulement Y */
}

/* Rotation */
.rotate {
  transform: rotate(45deg);
  transform: rotate(-90deg);
  transform: rotate(0.5turn); /* Un demi-tour */
}

/* Échelle */
.scale {
  transform: scale(1.5); /* 150% de la taille */
  transform: scale(2, 0.5); /* 200% largeur, 50% hauteur */
  transform: scaleX(1.5); /* Seulement largeur */
  transform: scaleY(0.8); /* Seulement hauteur */
}

/* Déformation (skew) */
.skew {
  transform: skew(15deg, 10deg); /* X et Y */
  transform: skewX(20deg); /* Seulement X */
  transform: skewY(-10deg); /* Seulement Y */
}

/* Transformations combinées */
.combined {
  transform: translate(50px, 30px) rotate(45deg) scale(1.2);
}

/* Point d'origine de transformation */
.transform-origin {
  transform-origin: center; /* Par défaut */
  transform-origin: top left;
  transform-origin: 50% 25%;
  transform-origin: 10px 20px;
}

b. Transformations 3D.code:
/* Perspective pour les effets 3D */
.perspective {
  perspective: 1000px;
  perspective-origin: center center;
}

/* Translations 3D */
.translate-3d {
  transform: translate3d(50px, 30px, 20px);
  transform: translateZ(50px); /* Profondeur */
}

/* Rotations 3D */
.rotate-3d {
  transform: rotateX(45deg); /* Rotation autour de X */
  transform: rotateY(60deg); /* Rotation autour de Y */
  transform: rotateZ(30deg); /* Rotation autour de Z */
  transform: rotate3d(1, 1, 0, 45deg); /* Axe personnalisé */
}

/* Échelles 3D */
.scale-3d {
  transform: scale3d(1.5, 1.2, 0.8);
  transform: scaleZ(2);
}

/* Style de transformation 3D */
.transform-style {
  transform-style: preserve-3d; /* Préserve la 3D pour les enfants */
  transform-style: flat; /* Aplati en 2D */
}

/* Visibilité de face arrière */
.backface {
  backface-visibility: visible; /* Par défaut */
  backface-visibility: hidden; /* Cache la face arrière */
}

/* Carte qui se retourne */
.flip-card {
  transform-style: preserve-3d;
  transition: transform 0.6s;
}

.flip-card:hover {
  transform: rotateY(180deg);
}

.flip-card-back {
  transform: rotateY(180deg);
  backface-visibility: hidden;
}

a. Propriétés de Transition.code:
/* Transition simple */
.transition-basic {
  transition: all 0.3s ease;
  transition: color 0.5s linear;
}

/* Propriétés spécifiques de transition */
.transition-properties {
  transition-property: color, background-color, transform;
  transition-duration: 0.3s, 0.5s, 0.2s;
  transition-timing-function: ease, ease-in-out, ease-out;
  transition-delay: 0s, 0.1s, 0.2s;
}

/* Fonctions de timing */
.timing-functions {
  transition-timing-function: linear; /* Vitesse constante */
  transition-timing-function: ease; /* Défaut */
  transition-timing-function: ease-in; /* Accélération */
  transition-timing-function: ease-out; /* Décélération */
  transition-timing-function: ease-in-out; /* Les deux */
  transition-timing-function: cubic-bezier(0.25, 0.1, 0.25, 1); /* Personnalisé */
}

/* Délais échelonnés */
.staggered {
  transition: transform 0.3s ease;
}

.staggered:nth-child(1) { transition-delay: 0.1s; }
.staggered:nth-child(2) { transition-delay: 0.2s; }
.staggered:nth-child(3) { transition-delay: 0.3s; }

