a. Keyframes et Animation.code:
/* Définition des keyframes */
@keyframes slideIn {
  from {
    transform: translateX(-100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

/* Keyframes avec pourcentages */
@keyframes bounce {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-20px);
  }
}

/* Animation complexe */
@keyframes complexMove {
  0% {
    transform: translate(0, 0) rotate(0deg);
    background-color: red;
  }
  25% {
    transform: translate(100px, 0) rotate(90deg);
    background-color: blue;
  }
  50% {
    transform: translate(100px, 100px) rotate(180deg);
    background-color: green;
  }
  75% {
    transform: translate(0, 100px) rotate(270deg);
    background-color: yellow;
  }
  100% {
    transform: translate(0, 0) rotate(360deg);
    background-color: red;
  }
}

/* Application des animations */
.slide-in {
  animation: slideIn 0.5s ease-out;
}

.bounce {
  animation: bounce 1s infinite;
}

.complex {
  animation: complexMove 4s linear infinite;
}

b. Propriétés d'Animation.code:
/* Propriétés complètes d'animation */
.animation-full {
  animation-name: slideIn;
  animation-duration: 2s;
  animation-timing-function: ease-in-out;
  animation-delay: 0.5s;
  animation-iteration-count: 3; /* ou infinite */
  animation-direction: alternate; /* normal, reverse, alternate, alternate-reverse */
  animation-fill-mode: forwards; /* none, forwards, backwards, both */
  animation-play-state: running; /* running, paused */
}

/* Raccourci animation */
.animation-shorthand {
  animation: slideIn 2s ease-in-out 0.5s 3 alternate forwards;
}

/* Animations multiples */
.multiple-animations {
  animation:
    slideIn 1s ease-out,
    bounce 2s ease-in-out 1s infinite,
    fadeIn 0.5s ease;
}

/* Contrôle par interaction */
.pause-on-hover {
  animation: rotate 2s linear infinite;
}

.pause-on-hover:hover {
  animation-play-state: paused;
}

/* Animation avec variables CSS */
.variable-animation {
  --duration: 2s;
  --delay: 0.5s;
  animation: slideIn var(--duration) ease var(--delay);
}

c. Animations Pratiques.code:
/* Animation de chargement */
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.loader {
  border: 4px solid #f3f3f3;
  border-top: 4px solid #3498db;
  border-radius: 50%;
  width: 50px;
  height: 50px;
  animation: spin 1s linear infinite;
}

/* Pulsation */
@keyframes pulse {
  0%, 100% {
    transform: scale(1);
    opacity: 1;
  }
  50% {
    transform: scale(1.1);
    opacity: 0.7;
  }
}

.pulse {
  animation: pulse 2s ease-in-out infinite;
}

/* Apparition en fondu */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.fade-in {
  animation: fadeIn 0.6s ease-out;
}

/* Animation de typewriter */
@keyframes typing {
  from {
    width: 0;
  }
  to {
    width: 100%;
  }
}

.typewriter {
  overflow: hidden;
  border-right: 2px solid #333;
  white-space: nowrap;
  animation: typing 3s steps(40, end), blink 0.75s step-end infinite;
}

@keyframes blink {
  from, to {
    border-color: transparent;
  }
  50% {
    border-color: #333;
  }
}

